        let mut join_set = JoinSet::new();

        for (i, prompt) in prompts.iter().enumerate() {
            let sem_clone = Arc::clone(&semaphore);

            // Spawn task with semaphore acquisition
            let handle = tokio::spawn(async move {
                let _permit = sem_clone.acquire().await.context("Failed to acquire inference permit")?;

                info!("[benchmark] [Parallel] Processing prompt: {}", prompt);

                // Placeholder for actual parallel inference logic
                let result = InferenceResult::new(
                    "parallel_execution".to_string(),
                    prompt.clone(),
                    Some(semaphore),
                );

                Ok::<InferenceResult, anyhow::Error>(result)
            });

            join_set.push(handle);
        }

        // Collect results
        let mut results = Vec::new();
        while let Some(res) = join_set.join_next().await {
            match res {
                Ok(result) => results.push(result),
                Err(e) => error!("[benchmark] Parallel task failed: {}", e),
            }
        }

