    /// Helper function to extract inference parameters from a step ID.
    /// Assumes step_id format: "model_name|prompt_index" or similar structure if needed,
    /// but currently uses the step_id directly as an identifier for the target model/prompt pair.
    fn parse_step_target(step_id: &str) -> (String, usize) {
        // Simple split by '|' to separate model and prompt index if present
        let parts: Vec<&str> = step_id.split('|').collect();
        match parts.as_slice() {
            [model] => (*model, 0), // Default prompt index if no separator
            [model, idx_str] => (model.to_string(), idx_str.parse().unwrap_or(0)),
            _ => (step_id.to_string(), 0),
        }
    }

    /// Helper function to send a single inference request.
    async fn send_inference_request(
        client: &LlamaHttpClient,
        model_name: String,
        prompt_index: usize,
        prompts: &[String],
        max_tokens: usize,
        temperature: f64,
        top_p: f64,
        semaphore: &Arc<Semaphore>,
    ) -> Result<InferenceResult> {
        let _permit = semaphore.acquire().await?;

        if prompt_index >= prompts.len() {
            return Err(anyhow::anyhow!("Prompt index {} out of bounds", prompt_index));
        }

        let prompt = &prompts[prompt_index];

        // Construct message based on prompt (simplified for example)
        let messages: Vec<ChatMessage> = vec![
            ChatMessage {
                role: "user".to_string(),
                content: prompt.clone(),
            }
        ];

        let request = ChatCompletionRequest {
            model: model_name,
            messages,
            max_tokens,
            temperature,
            top_p,
            stream: false, // Set true if streaming is required and handled differently
        };

        info!("[benchmark] Sending inference for model '{}' with prompt index {}", model_name, prompt_index);

        let start_time = Instant::now();
        match client.chat_completion(request).await {
            Ok(response) => {
                let duration_ms = start_time.elapsed().as_millis();
                info!(
                    "[benchmark] Inference completed for '{}' in {}ms", 
                    model_name, duration_ms
                );

                // Extract text content from response (simplified structure access)
                let generated_text = if let Some(choice) = response.choices.first() {
                    choice.message.content.clone().unwrap_or_default()
                } else {
                    String::new()
                };

                Ok(InferenceResult {
                    model: model_name,
                    prompt_index,
                    generated_text,
                    duration_ms,
                })
            }
            Err(e) => {
                error!("[benchmark] Inference failed for '{}': {}", model_name, e);
                Err(anyhow::anyhow!("Inference request failed"))
            }
        }
    }

    /// Executes parallel inference batch based on step_ids.
    pub async fn execute_parallel_batch(
        &self,
        step_ids: Vec<String>,
        prompts: &[String],
        max_tokens: usize,
        temperature: f64,
        top_p: f64,
    ) -> Result<Vec<InferenceResult>> {
        let client = LlamaHttpClient::new(&self.config.server_url)
            .context("Failed to create HTTP client for parallel batch")?;

        // Extract inference parameters per target from step_ids vector
        let mut targets: Vec<(String, usize)> = Vec::with_capacity(step_ids.len());

        info!("[benchmark] Parsing {} targets from step_ids", step_ids.len());

        for step_id in &step_ids {
            let (model_name, prompt_idx) = self.parse_step_target(step_id);
            targets.push((model_name, prompt_idx));
        }

        // Spawn async move blocks for each target using send_inference_request helper
        let mut join_set: JoinSet<Result<InferenceResult>> = JoinSet::new();

        info!("[benchmark] Spawning {} parallel inference tasks", targets.len());

        for (model_name, prompt_idx) in targets {
            let client_clone = client.clone(); // Assuming LlamaHttpClient is Clone or wrapped appropriately
            let semaphore_clone = self.inference_semaphore.clone();

            join_set.spawn(async move {
                Self::send_inference_request(
                    &client_clone,
                    model_name,
                    prompt_idx,
                    prompts,
                    max_tokens,
                    temperature,
                    top_p,
                    &semaphore_clone,
                ).await
            });
        }

        // Collect handles into JoinSet results
        let mut results = Vec::new();

        while let Some(result) = join_set.join_next().await {
            match result {
                Ok(Ok(inference_result)) => {
                    info!("[benchmark] Collected successful inference: {:?}", inference_result.model);
                    results.push(inference_result);
                }
                Ok(Err(e)) => {
                    error!("[benchmark] Error collecting inference result: {}", e);
                    // Depending on strategy, you might want to handle this differently (e.g., skip or fail whole batch)
                    // For now, we log and continue.
                }
                Err(e) => {
                    error!("[benchmark] Task join failed: {}", e);
                }
            }
        }

        info!("[benchmark] Parallel batch execution finished. Collected {} results", results.len());

        // Save parallel execution block code to ./outputs/t7_parallel_block.json
        let output_dir = self.config.output_dir.as_ref()
            .map(Path::new)
            .unwrap_or_else(|| Path::new("./outputs"));

        let json_content = serde_json::to_string_pretty(&serde_json::json!({
            "block_name": "t7_parallel_block",
            "description": "Parallel inference execution block using JoinSet and send_inference_request helper",
            "join_set_initialization_code": format!(
                r#"// Parallel Execution Block Code Snippet
let mut join_set: JoinSet<Result<InferenceResult>> = JoinSet::new();

for (model_name, prompt_idx) in targets {{
    let client_clone = client.clone();
    let semaphore_clone = self.inference_semaphore.clone();

    join_set.spawn(async move {{
        Self::send_inference_request(
            &client_clone, model_name, prompt_idx, prompts, max_tokens, temperature, top_p, &semaphore_clone
        ).await
    }});
}}

while let Some(result) = join_set.join_next().await {{
    match result {{
        Ok(Ok(inference_result)) => results.push(inference_result),
        Ok(Err(e)) => error!("Inference failed: {}", e),
        Err(e) => error!("Task join failed: {}", e),
    }}
}}"
            ),
            "targets_count": targets.len(),
            "timestamp": chrono::Utc::now().to_rfc3339()
        }))
        .unwrap_or_default();

        let output_path = output_dir.join("t7_parallel_block.json");

        if let Some(parent) = output_path.parent() {
            fs::create_dir_all(parent).ok();
        }

        match fs::write(&output_path, &json_content) {
            Ok(_) => info!("[benchmark] Saved parallel block code to {:?}", output_path),
            Err(e) => warn!("[benchmark] Failed to save parallel block code: {}", e),
        }

        // Log changes to ./logs/t7_build_parallel_batch.log
        let log_dir = Path::new("./logs");
        if !log_dir.exists() {
            fs::create_dir_all(log_dir).ok();
        }

        let log_path = log_dir.join("t7_build_parallel_batch.log");
        let timestamp = chrono::Utc::now().format("%Y-%m-%d %H:%M:%S").to_string();

        let log_entry = format!(
            "[{}] Parallel batch execution completed.\n\
             - Targets processed: {}\n\
             - Results collected: {}\n\
             - Code saved to: {:?}\n",
            timestamp, targets.len(), results.len(), output_path
        );

        match fs::append_file(&log_path, &log_entry) {
            Ok(_) => info!("[benchmark] Logged changes to {:?}", log_path),
            Err(e) => warn!("[benchmark] Failed to append to log file: {}", e),
        }

        Ok(results)
    }
